+# ---------------------------------------------------------------------
+# ars_make_log_density: wrap a density g into h(x) = log g(x).
+# h is vectorised, maps g(x) == 0 to -Inf, and stops loudly on
+# negative, NA/NaN, infinite or otherwise invalid density values.
+# Extra arguments (g_args) are passed on to g, e.g. dnorm(x, mean, sd).
+# ---------------------------------------------------------------------
+ars_make_log_density <- function(g, g_args) {
+  force(g)
+  force(g_args)
+  h <- function(x) {
+    x <- as.numeric(x)
+    if (length(x) == 0L) {
+      return(numeric(0))
+    }
+    gv <- suppressWarnings(tryCatch(do.call(g, c(list(x), g_args)),
+      error = function(e) stop("ars: density function 'g' failed to evaluate: ",
+                               conditionMessage(e), call. = FALSE)))
+    if (!is.numeric(gv)) {
+      stop("ars: density function 'g' must return numeric values.", call. = FALSE)
+    }
+    if (length(gv) != length(x)) {
+      gv <- suppressWarnings(tryCatch(
+        as.numeric(sapply(x, function(xi) do.call(g, c(list(xi), g_args)))),
+        error = function(e) stop("ars: density function 'g' failed to evaluate: ",
+                                 conditionMessage(e), call. = FALSE)))
+    }
+    if (length(gv) != length(x) || !is.numeric(gv)) {
+      stop("ars: density function 'g' must return one numeric value per input value.", call. = FALSE)
+    }
+    if (any(is.na(gv))) {
+      stop("ars: density function 'g' returned NA/NaN; densities must be non-negative numbers.", call. = FALSE)
+    }
+    if (any(gv < 0)) {
+      stop("ars: density function 'g' returned negative value(s); densities must be non-negative.", call. = FALSE)
+    }
+    if (any(!is.finite(gv))) {
+      stop("ars: density function 'g' returned non-finite (infinite) value(s).", call. = FALSE)
+    }
+    hv <- suppressWarnings(log(gv))
+    hv[gv == 0] <- -Inf
+    hv
+  }
+  h
+}
+
+# ---------------------------------------------------------------------
+# ars_probe: soft (non-throwing, except for negative densities)
+# evaluation of h at a single point. Returns NA_real_ when h is not a
+# finite number there, so search routines can keep looking elsewhere.
+# ---------------------------------------------------------------------
+ars_probe <- function(h, v) {
+  res <- tryCatch(suppressWarnings(h(v)),
+    error = function(e) e)
+  if (inherits(res, "error")) {
+    msg <- conditionMessage(res)
+    if (grepl("negative", msg, ignore.case = TRUE)) {
+      stop(res) # negative densities are never legitimate: fail loudly
+    }
+    return(NA_real_)
+  }
+  if (length(res) != 1L || !is.numeric(res) || is.na(res)) {
+    return(NA_real_)
+  }
+  as.numeric(res)
+}
+
+# ---------------------------------------------------------------------
+# ars_log_deriv: numeric first derivative of h by central differences,
+# falling back to one-sided differences at support boundaries.
+# ---------------------------------------------------------------------
+ars_log_deriv <- function(h, x, hvals = NULL) {
+  x <- as.numeric(x)
+  k <- length(x)
+  if (is.null(hvals)) {
+    hvals <- h(x)
+  }
+  hvals <- as.numeric(hvals)
+  out <- numeric(k)
+  for (i in seq_len(k)) {
+    xi <- x[i]
+    if (!is.finite(hvals[i])) {
+      stop("ars: cannot differentiate the log-density where it is not finite.", call. = FALSE)
+    }
+    eps <- 1e-5 * (1 + abs(xi))
+    fwd <- ars_probe(h, xi + eps)
+    bwd <- ars_probe(h, xi - eps)
+    if (is.finite(fwd) && is.finite(bwd)) {
+      out[i] <- (fwd - bwd) / (2 * eps)
+    } else if (is.finite(fwd)) {
+      out[i] <- (fwd - hvals[i]) / eps
+    } else if (is.finite(bwd)) {
+      out[i] <- (hvals[i] - bwd) / eps
+    } else {
+      stop("ars: cannot compute the log-density derivative; check 'g' and the domain.", call. = FALSE)
+    }
+  }
+  out
+}
+
+# ---------------------------------------------------------------------
+# ars_find_valid_point: locate a point with positive, finite density.
+# ---------------------------------------------------------------------
+ars_find_valid_point <- function(h, a, b) {
+  cands <- numeric(0)
+  if (is.finite(a) && is.finite(b)) {
+    cands <- a + (b - a) * seq(0.05, 0.95, length.out = 12L)
+  } else if (is.finite(a)) {
+    cands <- a + c(0.01, 0.1, 0.5, 1, 2, 5, 10, 20, 50, 100)
+  } else if (is.finite(b)) {
+    cands <- b - c(0.01, 0.1, 0.5, 1, 2, 5, 10, 20, 50, 100)
+  } else {
+    cands <- c(0, 1, -1, 2, -2, 5, -5, 10, -10, 20, -20, 50, -50, 100, -100)
+  }
+  for (v in cands) {
+    if (is.finite(ars_probe(h, v))) {
+      return(v)
+    }
+  }
+  for (m in c(500, 5000, 5e4)) {
+    for (v in c(m, -m)) {
+      if (v <= a || v >= b) {
+        next
+      }
+      if (is.finite(ars_probe(h, v))) {
+        return(v)
+      }
+    }
+  }
+  stop("ars: density evaluates to zero (or cannot be evaluated) everywhere tried on (a, b); check 'g' and the domain.", call. = FALSE)
+}
+
+# ---------------------------------------------------------------------
+# ars_find_mode: maximise h over a finite bracket (expand the bracket
+# while the optimum sits on an artificial infinite-domain edge).
+# ---------------------------------------------------------------------
+ars_find_mode <- function(h, a, b, x_start) {
+  lo <- if (is.finite(a)) a else x_start - 20
+  hi <- if (is.finite(b)) b else x_start + 20
+  if (!(lo < hi)) {
+    stop("ars: invalid mode-search interval.", call. = FALSE)
+  }
+  m <- x_start
+  for (it in 1:8) {
+    res <- suppressWarnings(tryCatch(optimize(h, interval = c(lo, hi),
+      maximum = TRUE, tol = 1e-10), error = function(e) NULL))
+    if (is.null(res)) {
+      break
+    }
+    m <- res$maximum
+    moved <- FALSE
+    if (!is.finite(a) && (m - lo) < 0.02 * (hi - lo)) {
+      lo <- lo - (hi - lo)
+      moved <- TRUE
+    }
+    if (!is.finite(b) && (hi - m) < 0.02 * (hi - lo)) {
+      hi <- hi + (hi - lo)
+      moved <- TRUE
+    }
+    if (!moved) {
+      break
+    }
+  }
+  if (!is.finite(ars_probe(h, m))) {
+    m <- x_start
+  }
+  m
+}
+
+# ---------------------------------------------------------------------
+# ars_estimate_scale: spread of the starting grid from the curvature
+# at the mode, sigma = 1 / sqrt(-h''(m)), with domain fallback.
+# ---------------------------------------------------------------------
+ars_estimate_scale <- function(h, m, a, b) {
+  e <- 1e-4 * (1 + abs(m))
+  hm <- ars_probe(h, m)
+  hp <- ars_probe(h, m + e)
+  hm2 <- ars_probe(h, m - e)
+  sigma <- 1
+  if (is.finite(hm) && is.finite(hp) && is.finite(hm2)) {
+    h2 <- (hp - 2 * hm + hm2) / e^2
+    if (is.finite(h2) && h2 < -1e-10) {
+      sigma <- 1 / sqrt(-h2)
+    }
+  }
+  if (!is.finite(sigma) || sigma <= 0) {
+    sigma <- 1
+  }
+  if (is.finite(a) && is.finite(b)) {
+    sigma <- min(sigma, (b - a) / 4)
+  }
+  max(sigma, 1e-8)
+}
+
+# ---------------------------------------------------------------------
+# ars_check_chords: a concave log-density lies below every chord.
+# A midpoint strictly above its chord proves non-log-concavity.
+# ---------------------------------------------------------------------
+ars_check_chords <- function(h, x, hvals, tol = 1e-6) {
+  k <- length(x)
+  if (k < 2L) {
+    return(invisible(TRUE))
+  }
+  for (j in seq_len(k - 1L)) {
+    mid <- 0.5 * (x[j] + x[j + 1L])
+    hm <- h(mid) # strict: invalid densities stop here
+    if (!is.finite(hm)) {
+      next # zero-density gap: sampling handles it
+    }
+    rhs <- 0.5 * (hvals[j] + hvals[j + 1L])
+    if (hm > rhs + tol * (1 + abs(rhs))) {
+      stop("ars: density appears to be non-log-concave (log-density lies above its chord).", call. = FALSE)
+    }
+  }
+  invisible(TRUE)
+}
+
+# __MORE__

