-# __MORE__
+# ---------------------------------------------------------------------
+# ars_trim_support: shrink infinite domain ends to the edge of the
+# support (where h turns from -Inf to finite). Removing zero-density
+# regions is exact: it discards no probability mass. This lets calls
+# such as ars(n, dexp) work without an explicit a = 0.
+# ---------------------------------------------------------------------
+ars_trim_support <- function(h, a, b, x_valid) {
+  if (!is.finite(a)) {
+    hi <- x_valid # last point known to have finite h
+    lo <- NA_real_
+    step <- 1
+    for (i in 1:60) {
+      cand <- x_valid - step
+      pv <- ars_probe(h, cand)
+      if (!is.finite(pv)) {
+        lo <- cand
+        break
+      }
+      hi <- cand
+      if (step > 1e15) {
+        break
+      }
+      step <- step * 2
+    }
+    if (is.finite(lo)) {
+      for (i in 1:60) {
+        mid <- 0.5 * (lo + hi)
+        if (is.finite(ars_probe(h, mid))) {
+          hi <- mid
+        } else {
+          lo <- mid
+        }
+      }
+      a <- hi
+    }
+  }
+  if (!is.finite(b)) {
+    lf <- x_valid # last point known to have finite h
+    rt <- NA_real_
+    step <- 1
+    for (i in 1:60) {
+      cand <- x_valid + step
+      pv <- ars_probe(h, cand)
+      if (!is.finite(pv)) {
+        rt <- cand
+        break
+      }
+      lf <- cand
+      if (step > 1e15) {
+        break
+      }
+      step <- step * 2
+    }
+    if (is.finite(rt)) {
+      for (i in 1:60) {
+        mid <- 0.5 * (lf + rt)
+        if (is.finite(ars_probe(h, mid))) {
+          lf <- mid
+        } else {
+          rt <- mid
+        }
+      }
+      b <- lf
+    }
+  }
+  c(a, b)
+}
+
+# ---------------------------------------------------------------------
+# ars_fallback_points: emergency starting grid when the modal grid
+# yields fewer than two usable abscissae (very narrow domains, modes
+# on a boundary).
+# ---------------------------------------------------------------------
+ars_fallback_points <- function(h, a, b, m, sigma) {
+  if (is.finite(a) && is.finite(b)) {
+    cands <- a + (b - a) * c(0.2, 0.4, 0.6, 0.8)
+  } else {
+    s <- max(sigma, 1e-3)
+    cands <- m + s * c(-3, -1.5, -0.5, 0.5, 1.5, 3, -5, 5)
+  }
+  cands <- cands[cands > a & cands < b]
+  keep <- logical(length(cands))
+  hv <- numeric(length(cands))
+  for (i in seq_along(cands)) {
+    pv <- ars_probe(h, cands[i])
+    if (is.finite(pv)) {
+      keep[i] <- TRUE
+      hv[i] <- pv
+    }
+  }
+  list(x = cands[keep], h = hv[keep])
+}
+
+# ---------------------------------------------------------------------
+# ars_extend_tails: grow the grid outward until the leftmost slope is
+# positive (left-unbounded) and the rightmost slope is negative
+# (right-unbounded), so the exponential envelope is integrable.
+# ---------------------------------------------------------------------
+ars_extend_tails <- function(h, a, b, x, hvals, hpvals, sigma) {
+  if (!is.finite(a)) {
+    guard <- 0L
+    while (hpvals[1L] <= 0 && guard < 50L) {
+      step <- max(2 * sigma, 0.5 * abs(x[1L]) + sigma, 1e-6)
+      cand <- x[1L] - step
+      hc <- ars_probe(h, cand)
+      if (!is.finite(hc)) {
+        break
+      }
+      d1 <- ars_log_deriv(h, cand, hvals = hc)
+      x <- c(cand, x)
+      hvals <- c(hc, hvals)
+      hpvals <- c(d1, hpvals)
+      guard <- guard + 1L
+    }
+    if (hpvals[1L] <= 0) {
+      stop("ars: cannot bracket the left tail (is the density log-concave?).", call. = FALSE)
+    }
+  }
+  if (!is.finite(b)) {
+    guard <- 0L
+    k <- length(x)
+    while (hpvals[k] >= 0 && guard < 50L) {
+      step <- max(2 * sigma, 0.5 * abs(x[k]) + sigma, 1e-6)
+      cand <- x[k] + step
+      hc <- ars_probe(h, cand)
+      if (!is.finite(hc)) {
+        break
+      }
+      d1 <- ars_log_deriv(h, cand, hvals = hc)
+      x <- c(x, cand)
+      hvals <- c(hvals, hc)
+      hpvals <- c(hpvals, d1)
+      k <- length(x)
+      guard <- guard + 1L
+    }
+    if (hpvals[length(x)] >= 0) {
+      stop("ars: cannot bracket the right tail (is the density log-concave?).", call. = FALSE)
+    }
+  }
+  list(x = x, h = hvals, hp = hpvals)
+}
+
+# ---------------------------------------------------------------------
+# ars_init_abscissae: build the starting grid. Uses user-supplied x0
+# when given (expanding a single value to a pair), otherwise centres a
+# grid on the modal region with curvature-based spacing.
+# ---------------------------------------------------------------------
+ars_init_abscissae <- function(h, a, b, x0 = NULL) {
+  if (!is.null(x0)) {
+    x <- x0
+    if (length(x) == 1L) {
+      base <- 1 + abs(x)
+      done <- FALSE
+      for (s in base * c(0.25, 0.5, 1, 2, 4, 8)) {
+        for (cand in c(x + s, x - s)) {
+          if (cand > a && cand < b && is.finite(ars_probe(h, cand))) {
+            x <- sort(c(x, cand))
+            done <- TRUE
+            break
+          }
+        }
+        if (done) {
+          break
+        }
+      }
+      if (!done) {
+        stop("ars: could not expand the single 'x0' value into a usable starting set.", call. = FALSE)
+      }
+    }
+    hv <- h(x) # strict: invalid starting densities stop here
+    if (any(!is.finite(hv))) {
+      stop("ars: 'x0' starting abscissae must have positive, finite density.", call. = FALSE)
+    }
+    ars_check_chords(h, x, hv)
+    return(x)
+  }
