+# ---------------------------------------------------------------------
+# ars: adaptive rejection sampling (Gilks & Wild, 1992).
+#
+# Args:
+#   n:  number of samples (single positive integer).
+#   g:  density function of x, vectorised, possibly unnormalised
+#       (e.g. dnorm, dexp, or function(x) exp(-x^2 / 2)). An R
+#       expression or string in x is also accepted. Extra arguments
+#       in ... are passed on to g.
+#   a, b: domain bounds with a < b (each finite or infinite).
+#       Aliases in ... : D / domain / interval (length-2 vector),
+#       lower / upper.
+#   x0: optional starting abscissae, strictly inside (a, b).
+#       Aliases in ... : x_init / xinit / abscissae / starting_points.
+#
+# Returns: a numeric vector of n samples from the target density.
+# Raises an error for invalid inputs and for densities that prove
+# to be non-log-concave during sampling.
+# ---------------------------------------------------------------------
+ars <- function(n, g, a = -Inf, b = Inf, x0 = NULL, ...) {
+  dots <- list(...)
+  take_alias <- function(names) {
+    for (nm in names) {
+      if (!is.null(dots[[nm]])) {
+        v <- dots[[nm]]
+        dots[[nm]] <<- NULL
+        return(v)
+      }
+    }
+    NULL
+  }
+  if (missing(n)) {
+    n <- take_alias(c("N", "n_samples", "nsamples", "size"))
+  }
+  if (missing(g)) {
+    g <- take_alias(c("density", "f", "func", "dg"))
+  }
+  dom <- take_alias(c("D", "domain", "interval", "lims", "bounds"))
